def check_weight_spread(stats: dict[str, float | int | None], max_cv: float = 1.5) -> tuple[str, str]:
    """Classify the weight coefficient of variation.

    Args:
        stats: n (row count) and cv (None when undefined).
        max_cv: Largest CV that passes.

    Returns:
        (status, reason), where status is SKIP, WARN or PASS.
    """
    n = stats["n"]
    cv = stats["cv"]
    if n is None or n < 2:
        return ("SKIP", "fewer than 2 rows")
    if cv is None:
        return ("SKIP", "cv undefined")
    if cv > max_cv:
        return ("WARN", f"cv {cv:.4f} above {max_cv}")
    return ("PASS", f"cv {cv:.4f}")

