def compare_share(metric: str, current_pct: float | None, prior_pct: float | None, tolerance: float = 0.10) -> dict[str, object] | None:
    """Return a stability result, or None when a share is missing."""
    if current_pct is not None and prior_pct is not None:
        change = abs(current_pct - prior_pct)
        return {"metric": metric, "change_pp": round(change, 4), "status": "WARN" if change > tolerance else "PASS"}
    return None
